using Xunit;

public class SymptomTest
{
    private readonly ISymptomService _symptomService;

    public SymptomTest(ISymptomService symptomService)
    {
        _symptomService = symptomService;
    }

    [Fact]
    public void AddNewSymptom_ValidInput_Success()
    {
        // Arrange
        var symptom = new Symptom { Name = "New Symptom" };

        // Act
        _symptomService.Add(symptom);

        // Assert
        Assert.Contains(symptom, _symptomService.GetAll());
    }

    [Fact]
    public void ViewAndUpdateSymptom_ValidId_Success()
    {
        // Arrange
        var symptom = new Symptom { Name = "Symptom 1" };
        _symptomService.Add(symptom);

        // Act
        symptom.Description = "Updated Description";
        _symptomService.Update(symptom);

        // Assert
        Assert.Equal("Updated Description", _symptomService.GetById(symptom.Id).Description);
    }

    [Fact]
    public void DeleteSymptom_NoConsultationRequests_Success()
    {
        // Arrange
        var symptom = new Symptom { Name = "Symptom 2" };
        _symptomService.Add(symptom);

        // Act
        _symptomService.Delete(symptom.Id);

        // Assert
        Assert.DoesNotContain(symptom, _symptomService.GetAll());
    }

    [Fact]
    public void DeleteSymptom_ConsultationRequestExists_Error()
    {
        // Arrange
        var symptom = new Symptom { Name = "Symptom 3" };
        _symptomService.Add(symptom);

        // Precondition: Create a consultation request using the symptom
        // ...

        // Act & Assert
        Assert.Throws<Exception>(() => _symptomService.Delete(symptom.Id));
    }
}
